        private static void BuildAnimatedRuns(
            TextBlock target,
            string text,
            List<Run> runStore)
        {
            target.Inlines.Clear();

            runStore.Clear();


            foreach (char character in text)
            {
                var run =
                    new Run(
                        character.ToString());


                target.Inlines.Add(
                    run);


                runStore.Add(
                    run);
            }
        }


        private void RefreshAuraTextColours()
        {
            ApplyAuraColours(
                backgroundIllusionaryRuns,
                5,
                true);


            ApplyAuraColours(
                oddsRuns,
                4,
                true);


            ApplyAuraColours(
                summaryIllusionaryRuns,
                3,
                false);


            ApplyAuraColours(
                summaryChanceIllusionaryRuns,
                3,
                false);


            ApplyAuraColours(
                tableIllusionaryRuns,
                3,
                false);
        }


        private void ApplyAuraColours(
            List<Run> runs,
            int blueLetterCount,
            bool strongerBackgroundEffect)
        {
            // First reset all letters.

            foreach (Run run in runs)
            {
                if (
                    string.IsNullOrWhiteSpace(
                        run.Text)
                   )
                {
                    continue;
                }


                double normalColourRoll =
                    auraRandom.NextDouble();


                if (strongerBackgroundEffect)
                {
                    run.Foreground =
                        normalColourRoll < 0.28
                            ? AuraDim
                            : AuraBase;
                }
                else
                {
                    run.Foreground =
                        normalColourRoll < 0.18
                            ? AuraDim
                            : AuraBase;
                }
            }


            // Pick random characters to become the
            // one darker-blue colour.

            List<Run> blueRuns =
                runs
                    .Where(
                        run =>
                            !string.IsNullOrWhiteSpace(
                                run.Text))
                    .OrderBy(
                        _ =>
                            auraRandom.Next())
                    .Take(
                        blueLetterCount)
                    .ToList();


            foreach (Run run in blueRuns)
            {
                run.Foreground =
                    AuraBlue;
            }
        }


        // =========================================================
        // ADD SESSION
        // =========================================================

        private void AddSession()
        {
            var dialog =
                new SessionEditor
                {
                    Owner =
                        this
                };


            if (
                dialog.ShowDialog()
                ==
                true
                &&
                dialog.Result
                !=
                null
               )
            {
                sessions.Add(
                    dialog.Result);


                UpdateSummary();
            }
        }


        // =========================================================
        // EDIT SESSION
        // =========================================================

        private void EditSession()
        {
            if (
                SessionsTable.SelectedItem
                is not CyberspaceSession selected
               )
            {
                MessageBox.Show(
                    this,
                    "Select a session to edit.");


                return;
            }


            var dialog =
                new SessionEditor(
                    selected)
                {
                    Owner =
                        this
                };


            if (
                dialog.ShowDialog()
                ==
                true
                &&
                dialog.Result
                !=
                null
               )
            {
                int index =
                    sessions.IndexOf(
                        selected);


                sessions[index] =
                    dialog.Result;


                UpdateSummary();
            }
        }


        // =========================================================
        // DELETE SESSION
        // =========================================================

        private void DeleteSession()
        {
            if (
                SessionsTable.SelectedItem
                is not CyberspaceSession selected
               )
            {
                MessageBox.Show(
                    this,
                    "Select a session to delete.");


                return;
            }


            var answer =
                MessageBox.Show(
                    this,
                    $"Delete Cyberspace #{selected.Number}?",
                    "Delete session",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Question);


            if (
                answer
                ==
                MessageBoxResult.Yes
               )
            {
                sessions.Remove(
                    selected);


                UpdateSummary();
            }
        }


        // =========================================================
        // SUMMARY
        // =========================================================

        private void UpdateSummary()
        {
            for (
                int i = 0;
                i < sessions.Count;
                i++
                )
            {
                sessions[i].Number =
                    i + 1;
            }


            long rolls =
                sessions.Sum(
                    session =>
                        session.TotalRolls);


            TotalRollsText.Text =
                rolls.ToString(
                    "N0");


            TotalMetaText.Text =
                sessions
                    .Sum(
                        session =>
                            (long)
                            session.Metas)
                    .ToString(
                        "N0");


            TotalIllusionaryText.Text =
                sessions
                    .Sum(
                        session =>
                            (long)
                            session.Illusionaries)
                    .ToString(
                        "N0");


            OverallChanceText.Text =
                CyberspaceSession
                    .FormatChance(
                        rolls);


            SessionCountText.Text =
                $"{sessions.Count} cyberspace"
                +
                (
                    sessions.Count
                    ==
                    1
                        ? ""
                        : "s"
                );


            SessionsTable
                .Items
                .Refresh();
        }
    }


    // =============================================================
    // SESSION DATA
    // =============================================================

    public class CyberspaceSession
    {
        public int Number
        {
            get;
            set;
        }


        public DateTime Date
        {
            get;
            set;
        }
        =
        DateTime.Today;


        public int Warps
        {
            get;
            set;
        }


        public bool PlcEnabled
        {
            get;
            set;
        }


        public int TidalWaveShifters
        {
            get;
            set;
        }


        public long BaseRolls
        {
            get;
            set;
        }


        public long PlcExtraRolls
        {
            get;
            set;
        }


        public long TotalRolls
        {
            get;
            set;
        }


        public int Metas
        {
            get;
            set;
        }


        public int Illusionaries
        {
            get;
            set;
        }


        public string ChanceDisplay
            =>
            FormatChance(
                TotalRolls);


        public static string FormatChance(
            long rolls)
        {
            if (
                rolls
                <=
                0
               )
            {
                return
                    "0.00%";
            }


            double chance =
                100
                *
                (
                    1
                    -
                    Math.Pow(
                        1
                        -
                        1.0
                        /
                        10_000_000,
                        rolls)
                );


            if (
                chance
                <
                0.01
               )
            {
                return
                    "<0.01%";
            }


            if (
                chance
                >=
                99.995
               )
            {
                return
                    ">99.99%";
            }


            return
                $"{chance:F2}%";
        }
    }


