        private void BuildEditorAnimatedRuns(
            TextBlock target,
            string text)
        {
            target.Inlines.Clear();

            editorIllusionaryRuns.Clear();


            foreach (char character in text)
            {
                var run =
                    new Run(
                        character.ToString());


                target.Inlines.Add(
                    run);


                editorIllusionaryRuns.Add(
                    run);
            }
        }


        private void RefreshEditorIllusionaryColours()
        {
            foreach (Run run in editorIllusionaryRuns)
            {
                if (
                    string.IsNullOrWhiteSpace(
                        run.Text)
                   )
                {
                    continue;
                }


                run.Foreground =
                    editorAuraRandom.NextDouble()
                    <
                    0.18
                        ? EditorAuraDim
                        : EditorAuraBase;
            }


            List<Run> blueRuns =
                editorIllusionaryRuns
                    .Where(
                        run =>
                            !string.IsNullOrWhiteSpace(
                                run.Text))
                    .OrderBy(
                        _ =>
                            editorAuraRandom.Next())
                    .Take(
                        3)
                    .ToList();


            foreach (Run run in blueRuns)
            {
                run.Foreground =
                    EditorAuraBlue;
            }
        }


