        // =========================================================

        private static bool ReadCount(
            TextBox input,
            out int value)
        {
            return
                int.TryParse(
                    input.Text.Trim(),
                    out value)
                &&
                value
                >=
                0;
        }


        // =========================================================
        // PLC EXTRA ROLLS
        // =========================================================

        private static long CalculatePlcExtraRolls(
            long baseRolls)
        {
            if (
                baseRolls
                <
                30
               )
            {
                return
                    0;
            }


            long completedExtraGroups =
                (
                    baseRolls
                    -
                    30L
                )
                /
                25L;


            return
                completedExtraGroups
                *
                5L;
        }


        // =========================================================
        // LIVE ROLL PREVIEW
        // =========================================================

        private void UpdateSubtotal()
        {
            if (
                !ReadCount(
                    warpInput,
                    out int warps)
                ||
                !ReadCount(
                    tidalInput,
                    out int tidals)
               )
            {
                subtotalText.Text =
                    "Enter valid potion quantities.";


                return;
            }


            long potionRolls =
                warps
                *
                2_000L
                +
                tidals
                *
                10_000L;


            long baseRolls =
                potionRolls;


            bool usingActualRolls =
                !string.IsNullOrWhiteSpace(
                    rollsInput.Text);


            if (
                usingActualRolls
               )
            {
                if (
                    !long.TryParse(
                        rollsInput.Text.Trim(),
                        out baseRolls)
                    ||
                    baseRolls
                    <
                    0
                   )
                {
                    subtotalText.Text =
                        $"Potion rolls available: {potionRolls:N0}\n"
                        +
                        "Enter a valid actual-roll amount.";


                    return;
                }
            }


            long plcExtra =
                plcInput.IsChecked
                ==
                true
                    ?
                    CalculatePlcExtraRolls(
                        baseRolls)
                    :
                    0;


            long trackedTotal =
                baseRolls
                +
                plcExtra;


            string sourceLine =
                usingActualRolls
                    ?
                    $"Actual rolls used: {baseRolls:N0}"
                    :
                    $"Rolls being counted: {baseRolls:N0}";


            subtotalText.Text =
                $"Potion rolls available: {potionRolls:N0}\n"
                +
                sourceLine
                +
                (
                    plcInput.IsChecked
                    ==
                    true
                        ?
                        $"\nPLC extra rolls: {plcExtra:N0}"
                        :
                        ""
                )
                +
                $"\nTracked total: {trackedTotal:N0}";
        }


        // =========================================================
        // SAVE SESSION
        // =========================================================

        private void SaveSession()
        {
            errorText.Text =
                "";


            if (
                dateInput.SelectedDate
                ==
                null
               )
            {
                errorText.Text =
                    "Choose a valid date.";


                return;
            }


            if (
                !ReadCount(
                    warpInput,
                    out int warps)
                ||
                !ReadCount(
                    tidalInput,
                    out int tidals)
                ||
                !ReadCount(
                    metaInput,
                    out int metas)
                ||
                !ReadCount(
                    illusionaryInput,
                    out int illusionaries)
               )
            {
                errorText.Text =
                    "Quantities must be whole numbers of zero or more.";


                return;
            }


            long potionRolls =
                warps
                *
                2_000L
                +
                tidals
                *
                10_000L;


            long baseRolls =
                potionRolls;


            if (
                !string.IsNullOrWhiteSpace(
                    rollsInput.Text)
               )
            {
                if (
                    !long.TryParse(
                        rollsInput.Text.Trim(),
                        out baseRolls)
                   )
                {
                    errorText.Text =
                        "Enter actual rolls using whole numbers "
                        +
                        "and digits only.";


                    return;
                }
            }


            if (
                baseRolls
                <=
                0
                ||
                baseRolls
                >
                MaximumRolls
               )
            {
                errorText.Text =
                    "Actual rolls must be from "
                    +
                    "1 to 1,000,000,000,000.";


                return;
            }


            long plcExtraRolls =
                plcInput.IsChecked
                ==
                true
                    ?
                    CalculatePlcExtraRolls(
                        baseRolls)
                    :
                    0;


            long totalRolls =
                baseRolls
                +
                plcExtraRolls;


            if (
                totalRolls
                >
                MaximumRolls
               )
            {
                errorText.Text =
                    "The final tracked total is above "
                    +
                    "1,000,000,000,000 rolls.";


                return;
            }


            if (
                (long)
                metas
                +
                illusionaries
                >
                totalRolls
               )
            {
                errorText.Text =
                    "Aura results cannot exceed the total rolls.";


                return;
            }


            Result =
                new CyberspaceSession
                {
                    Date =
                        dateInput
                            .SelectedDate
                            .Value
                            .Date,

                    Warps =
                        warps,

                    PlcEnabled =
                        plcInput.IsChecked
                        ==
                        true,

                    TidalWaveShifters =
                        tidals,

                    BaseRolls =
                        baseRolls,

                    PlcExtraRolls =
                        plcExtraRolls,

                    TotalRolls =
                        totalRolls,

                    Metas =
                        metas,

                    Illusionaries =
                        illusionaries
                };


            DialogResult =
                true;
        }
    }
}

