                {
                    views[i].Visibility = i == index ? Visibility.Visible : Visibility.Collapsed;
                    buttons[i].Background = PotionTrackerPanel.Colour(i == index ? (index == 1 ? "#321127" : index == 0 ? "#08172F" : "#12121B") : "#0B0D18");
                    buttons[i].BorderBrush = PotionTrackerPanel.Colour(i == index ? (index == 1 ? "#FF46B6" : index == 0 ? "#2857A0" : "#62517F") : "#30334F");
                }
            }
            for (int i = 0; i < names.Length; i++)
            {
                int index = i;
                FrameworkElement title;
                if (i == 0)
                {
                    var label = new TextBlock { Text = names[i], FontSize = 14, FontWeight = FontWeights.Bold };
                    label.Foreground = DreamspaceArt.Wave(label, new[] { "#2452A0", "#2452A0", "#78A9F0", "#2452A0", "#2452A0" }, 6.0);
                    title = label;
                }
                else if (i == 1)
                    title = DreamspaceArt.AuraLabel(names[i], 14);
                else
                    title = GlitchedArt.AuraLabel(names[i]);
                title.HorizontalAlignment = HorizontalAlignment.Center;
                title.VerticalAlignment = VerticalAlignment.Center;
                title.IsHitTestVisible = false;
                var button = new Button
                {
                    Content = title,
                    Margin = new Thickness(0, 0, 10, 0),
                    MinWidth = 130,
                    Height = 44,
                    Padding = new Thickness(12, 6, 12, 6),
                    HorizontalContentAlignment = HorizontalAlignment.Center,
                    VerticalContentAlignment = VerticalAlignment.Center
                };
                System.Windows.Automation.AutomationProperties.SetName(button, names[i]);
                button.Click += (_, _) => Select(index);
                buttons.Add(button);
                navigation.Children.Add(button);
            }
            Content = shell;
            Select(0);
        }
    }

    public sealed class PotionBiomeSession
    {
        public DateTime Date { get; set; } = DateTime.Today;
        public int Oblivion { get; set; }
        public int Godlike { get; set; }
        public int Heavenly { get; set; }
        public int Bound { get; set; }
        public int Goddess { get; set; }
        public int Borealis { get; set; }
        public int Dreammetric { get; set; }
        public int Glitch { get; set; }
        public int Oppression { get; set; }
        public long Total => (long)Oblivion + Godlike + Heavenly + Bound + Goddess;
    }

    public sealed class PotionTrackerPanel : Grid
    {
        private readonly string biome;
        private readonly ObservableCollection<PotionBiomeSession> sessions = new();
        private readonly DataGrid table;
        private readonly TextBlock total = new();
        private readonly TextBlock count = new();
        private readonly TextBlock[] values = new TextBlock[5];
        private readonly TextBlock borealisTotal = new();
        private readonly TextBlock dreammetricTotal = new();
        internal static readonly string[] PotionNames = { "Oblivion", "Godlike", "Heavenly", "Potion of Bound", "Tear of the Goddess" };
        internal static Brush Colour(string hex) => (Brush)new BrushConverter().ConvertFromString(hex)!;
        internal static TextBlock PotionLabel(int index)
        {
            var label = new TextBlock { Text = PotionNames[index], FontWeight = FontWeights.Bold, FontSize = 14, TextWrapping = TextWrapping.Wrap };
            if (index < 3)
            {
                string[][] colours = {
                    new[] { "#AC55FF", "#160426", "#AC55FF" },
                    new[] { "#FFFF00", "#FF3030", "#00FFFF", "#FFFF00" },
                    new[] { "#FFFFFF", "#FF85D0", "#FFFFFF" }
                };
                label.Foreground = DreamspaceArt.Wave(label, colours[index]);
            }
            else label.Foreground = DreamspaceArt.Wave(label, new[] { index == 3 ? "#4285FF" : "#ED97FF", "#FFFFFF", index == 3 ? "#4285FF" : "#ED97FF" });
            return label;
        }
        public PotionTrackerPanel(string biome)
        {
            this.biome = biome;
            Margin = new Thickness(30, 18, 30, 24);
            RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            RowDefinitions.Add(new RowDefinition());
            RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            bool dream = biome == "Dreamspace";
            {
                var art = dream ? DreamspaceArt.Background() : GlitchedArt.Background();
                if (dream)
                {
                    art.Margin = new Thickness(-16, -10, -16, -10);
                    art.SizeChanged += (_, _) =>
                        art.Clip = new RectangleGeometry(new Rect(0, 0, art.ActualWidth, art.ActualHeight), 8, 8);
                }
                SetRowSpan(art, 5); Children.Add(art);
            }
            var heading = new StackPanel();
            heading.Children.Add(new TextBlock { Text = biome + " Tracker", FontSize = 28, Foreground = Brushes.White });
            total.FontSize = 17; total.Foreground = Colour("#BCC4E6"); total.Margin = new Thickness(0, 10, 0, 20);
            heading.Children.Add(total);
            {
                var auras = new System.Windows.Controls.Primitives.UniformGrid { Columns = 2, Margin = new Thickness(0, 0, 0, 18) };
                var labels = dream ? new[] { "Borealis", "Dreammetric" } : new[] { "Glitch", "Oppression" };
                var totals = new[] { borealisTotal, dreammetricTotal };
                for (int i = 0; i < 2; i++)
                {
                    var stack = new StackPanel();
                    stack.Children.Add(dream ? DreamspaceArt.AuraLabel(labels[i]) : GlitchedArt.AuraLabel(labels[i]));
                    totals[i].FontSize = 23; totals[i].Foreground = Brushes.White; totals[i].Margin = new Thickness(0, 8, 0, 0);
                    stack.Children.Add(totals[i]);
                    auras.Children.Add(new Border { Child = stack, CornerRadius = new CornerRadius(10), Padding = new Thickness(16), Margin = new Thickness(0, 0, 10, 0), Background = Colour(dream ? "#D52B122C" : "#D509101B"), BorderBrush = Colour(dream ? "#915079" : "#365B68"), BorderThickness = new Thickness(1) });
                }
                heading.Children.Add(auras);
            }
            Children.Add(heading);
            var cards = new System.Windows.Controls.Primitives.UniformGrid { Columns = 5, Margin = new Thickness(0, 0, 0, 20) };
            for (int i = 0; i < 5; i++)
            {
                var stack = new StackPanel(); stack.Children.Add(PotionLabel(i));
                values[i] = new TextBlock { FontSize = 23, Foreground = Brushes.White, Margin = new Thickness(0, 7, 0, 0) };
                stack.Children.Add(values[i]);
                if (i == 4) stack.Children.Add(new TextBlock { Text = "Event potion", Foreground = Colour("#AEB6DE"), FontSize = 11, Margin = new Thickness(0, 4, 0, 0) });
                cards.Children.Add(new Border { Child = stack, Padding = new Thickness(12), Margin = new Thickness(0, 0, 10, 0), Background = Colour(dream ? "#D52B122C" : "#101329"), BorderBrush = Colour(dream ? "#915079" : "#30365F"), BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(10) });
            }
            SetRow(cards, 1); Children.Add(cards);
            count.Foreground = Colour("#BCC4E6"); count.Margin = new Thickness(0, 0, 0, 12);
            SetRow(count, 2); Children.Add(count);
            table = new DataGrid
            {
                ItemsSource = sessions,
                AutoGenerateColumns = false,
                IsReadOnly = true,
                CanUserAddRows = false,
                CanUserDeleteRows = false,
                SelectionMode = DataGridSelectionMode.Single,
                Background = Colour(dream ? "#B5190B23" : "#AE050A12"),
                Foreground = Brushes.White,
                RowBackground = Colour(dream ? "#CF29112D" : "#101329"),
                AlternatingRowBackground = Colour(dream ? "#CF361539" : "#151A30"),
                BorderBrush = Colour("#30365F"),
                GridLinesVisibility = DataGridGridLinesVisibility.None,
                HeadersVisibility = DataGridHeadersVisibility.Column,
                RowHeight = 44,
                ColumnHeaderHeight = 66,
                FontSize = 13
            };
            var headerStyle = new Style(typeof(System.Windows.Controls.Primitives.DataGridColumnHeader));
            headerStyle.Setters.Add(new Setter(Control.BackgroundProperty, Colour(dream ? "#491D43" : "#171C34")));
            headerStyle.Setters.Add(new Setter(Control.ForegroundProperty, Brushes.White));
            headerStyle.Setters.Add(new Setter(Control.PaddingProperty, new Thickness(10)));
            table.ColumnHeaderStyle = headerStyle;
            var cellStyle = new Style(typeof(DataGridCell));
            cellStyle.Setters.Add(new Setter(Control.PaddingProperty, new Thickness(8)));
            cellStyle.Setters.Add(new Setter(Control.VerticalContentAlignmentProperty, VerticalAlignment.Center));
            {
                Brush selection = dream
                    ? DreamspaceArt.Wave(table, new[] { "#75235B", "#B24A87", "#EBA8D2", "#75235B" }, 3.5)
                    : GlitchedArt.SelectionBrush(table);
                foreach (var key in new[] { SystemColors.HighlightBrushKey, SystemColors.InactiveSelectionHighlightBrushKey }) table.Resources[key] = selection;
                foreach (var key in new[] { SystemColors.HighlightTextBrushKey, SystemColors.InactiveSelectionHighlightTextBrushKey }) table.Resources[key] = Brushes.White;
                var selected = new Trigger { Property = DataGridCell.IsSelectedProperty, Value = true };
                selected.Setters.Add(new Setter(Control.BackgroundProperty, selection));
                selected.Setters.Add(new Setter(Control.ForegroundProperty, Brushes.White));
                selected.Setters.Add(new Setter(Control.BorderBrushProperty, Brushes.Transparent));
                cellStyle.Triggers.Add(selected);
                var rows = new Style(typeof(DataGridRow));
                var rowSelected = new Trigger { Property = DataGridRow.IsSelectedProperty, Value = true };
                rowSelected.Setters.Add(new Setter(Control.BackgroundProperty, selection));
                rowSelected.Setters.Add(new Setter(Control.ForegroundProperty, Brushes.White));
                rows.Triggers.Add(rowSelected); table.RowStyle = rows;
                table.RowHeight = 38;
            }
            table.CellStyle = cellStyle;
            table.Columns.Add(new DataGridTextColumn { Header = "Date", Binding = new System.Windows.Data.Binding("Date") { StringFormat = "dd/MM/yyyy" }, Width = new DataGridLength(1, DataGridLengthUnitType.Star) });
            string[] properties = { "Oblivion", "Godlike", "Heavenly", "Bound", "Goddess" };
            for (int i = 0; i < 5; i++)
                table.Columns.Add(new DataGridTextColumn { Header = PotionLabel(i), Binding = new System.Windows.Data.Binding(properties[i]) { StringFormat = "N0" }, MinWidth = i >= 3 ? 140 : 80, Width = new DataGridLength(i >= 3 ? 1.45 : 1, DataGridLengthUnitType.Star) });
            table.Columns.Add(new DataGridTextColumn { Header = "Total", Binding = new System.Windows.Data.Binding("Total") { StringFormat = "N0" }, Width = new DataGridLength(1, DataGridLengthUnitType.Star) });
            foreach (var name in (dream ? new[] { "Borealis", "Dreammetric" } : new[] { "Glitch", "Oppression" }))
                table.Columns.Add(new DataGridTextColumn { Header = dream ? DreamspaceArt.AuraLabel(name) : GlitchedArt.AuraLabel(name), Binding = new System.Windows.Data.Binding(name) { StringFormat = "N0" }, MinWidth = 105, Width = new DataGridLength(1, DataGridLengthUnitType.Star) });
