            var edit = new Button { Content = "Edit selected", Margin = new Thickness(0, 0, 10, 0) };
            var delete = new Button { Content = "Delete selected", Foreground = Colour("#FFA9BD") };
            add.Click += (_, _) => Edit(null);
            edit.Click += (_, _) => { if (table.SelectedItem is PotionBiomeSession session) Edit(session); };
            delete.Click += (_, _) =>
            {
                if (table.SelectedItem is PotionBiomeSession session && MessageBox.Show(Window.GetWindow(this), "Delete this " + biome + " session?", "Delete session", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
                { sessions.Remove(session); RefreshTotals(); }
            };
            edit.IsEnabled = delete.IsEnabled = false;
            table.SelectionChanged += (_, _) => { edit.IsEnabled = delete.IsEnabled = table.SelectedItem != null; };
            actions.Children.Add(add); actions.Children.Add(edit); actions.Children.Add(delete);
            SetRow(actions, 4); Children.Add(actions);
            if (dream)
            {
                var edges = DreamspaceArt.SideBorders();
                edges.Margin = new Thickness(-16, -10, -16, -10);
                SetRowSpan(edges, 5); SetZIndex(edges, 10); Children.Add(edges);
            }
            if (!dream)
            {
                var frame = GlitchedArt.BorderEffect();
                SetRowSpan(frame, 5); SetZIndex(frame, 19); Children.Add(frame);
                var burst = GlitchedArt.Bursts();
                SetRowSpan(burst, 5); SetZIndex(burst, 20); Children.Add(burst);
            }
            if (!TrackerStorage.Attach(sessions, biome == "Dreamspace" ? "dreamspace.json" : "glitched.json"))
            {
                actions.IsEnabled = false;
                table.IsEnabled = false;
            }
            RefreshTotals();
        }
        private void Edit(PotionBiomeSession? existing)
        {
            var dialog = new PotionSessionEditor(biome, existing) { Owner = Window.GetWindow(this) };
            if (dialog.ShowDialog() != true || dialog.Result == null) return;
            if (existing == null) sessions.Add(dialog.Result);
            else sessions[sessions.IndexOf(existing)] = dialog.Result;
            table.SelectedItem = dialog.Result;
            RefreshTotals();
        }
        private void RefreshTotals()
        {
            long[] sums = { sessions.Sum(s => (long)s.Oblivion), sessions.Sum(s => (long)s.Godlike), sessions.Sum(s => (long)s.Heavenly), sessions.Sum(s => (long)s.Bound), sessions.Sum(s => (long)s.Goddess) };
            for (int i = 0; i < 5; i++) values[i].Text = sums[i].ToString("N0");
            borealisTotal.Text = sessions.Sum(s => (long)(biome == "Dreamspace" ? s.Borealis : s.Glitch)).ToString("N0");
            dreammetricTotal.Text = sessions.Sum(s => (long)(biome == "Dreamspace" ? s.Dreammetric : s.Oppression)).ToString("N0");
            total.Text = $"Total potions used: {sums.Sum():N0}";
            count.Text = $"Session history · {sessions.Count:N0} sessions";
        }
    }

    public sealed class PotionSessionEditor : Window
    {
        public PotionBiomeSession? Result { get; private set; }
        public PotionSessionEditor(string biome, PotionBiomeSession? existing)
        {
            Title = (existing == null ? "Add " : "Edit ") + biome + " session";
            Width = 460; Height = Math.Min(650, SystemParameters.WorkArea.Height);
            WindowStartupLocation = WindowStartupLocation.CenterOwner;
            Background = PotionTrackerPanel.Colour(biome == "Dreamspace" ? "#200D26" : "#080C1D"); Foreground = Brushes.White;
            FontFamily = new FontFamily("Segoe UI"); FontWeight = FontWeights.Bold;
            var panel = new StackPanel { Margin = new Thickness(24) };
            var dialogRoot = new Grid();
            dialogRoot.Children.Add(biome == "Dreamspace" ? DreamspaceArt.Background() : GlitchedArt.Background());
            dialogRoot.Children.Add(new ScrollViewer { Content = panel, VerticalScrollBarVisibility = ScrollBarVisibility.Auto });
            Content = dialogRoot;
            panel.Children.Add(new TextBlock { Text = Title, FontSize = 24, Margin = new Thickness(0, 0, 0, 20) });
            panel.Children.Add(new TextBlock { Text = "Date", Margin = new Thickness(0, 0, 0, 6) });
            var date = new DatePicker { SelectedDate = existing?.Date ?? DateTime.Today, Margin = new Thickness(0, 0, 0, 16) };
            panel.Children.Add(date);
            int[] initial = { existing?.Oblivion ?? 0, existing?.Godlike ?? 0, existing?.Heavenly ?? 0, existing?.Bound ?? 0, existing?.Goddess ?? 0 };
            var inputs = new TextBox[5];
            var eventPanel = new StackPanel();
            for (int i = 0; i < 5; i++)
            {
                var target = i == 4 ? eventPanel : panel;
                target.Children.Add(PotionTrackerPanel.PotionLabel(i));
                inputs[i] = new TextBox { Text = initial[i].ToString(), FontSize = 16, Padding = new Thickness(10), Margin = new Thickness(0, 6, 0, 16), Background = PotionTrackerPanel.Colour(biome == "Dreamspace" ? "#421B42" : "#171D35"), Foreground = Brushes.White, BorderBrush = PotionTrackerPanel.Colour("#424B76"), CaretBrush = Brushes.White };
                target.Children.Add(inputs[i]);
            }
            eventPanel.Children.Add(new TextBlock { Text = "Summer-exclusive potion", Foreground = PotionTrackerPanel.Colour("#AEB6DE"), Margin = new Thickness(0, 0, 0, 12) });
            panel.Children.Add(new Expander { Header = "Event potions", Content = eventPanel, IsExpanded = initial[4] > 0, Foreground = Brushes.White, Margin = new Thickness(0, 0, 0, 18) });
            var auraInputs = new TextBox[2];
            {
                panel.Children.Add(new TextBlock { Text = "Auras obtained", FontSize = 19, Margin = new Thickness(0, 0, 0, 12) });
                string[] auraNames = biome == "Dreamspace" ? new[] { "Borealis", "Dreammetric" } : new[] { "Glitch", "Oppression" };
                int[] auraInitial = biome == "Dreamspace" ? new[] { existing?.Borealis ?? 0, existing?.Dreammetric ?? 0 } : new[] { existing?.Glitch ?? 0, existing?.Oppression ?? 0 };
                for (int i = 0; i < 2; i++)
                {
                    panel.Children.Add(biome == "Dreamspace" ? DreamspaceArt.AuraLabel(auraNames[i]) : GlitchedArt.AuraLabel(auraNames[i]));
                    auraInputs[i] = new TextBox { Text = auraInitial[i].ToString(), FontSize = 16, Padding = new Thickness(10), Margin = new Thickness(0, 6, 0, 16), Background = PotionTrackerPanel.Colour(biome == "Dreamspace" ? "#421B42" : "#171D35"), Foreground = Brushes.White, CaretBrush = Brushes.White };
                    panel.Children.Add(auraInputs[i]);
                }
                if (biome == "Dreamspace") dialogRoot.Children.Add(DreamspaceArt.SideBorders());
                else { var frame = GlitchedArt.BorderEffect(); frame.Margin = new Thickness(6); dialogRoot.Children.Add(frame); }
            }
            var actions = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
            var cancel = new Button { Content = "Cancel", IsCancel = true, Padding = new Thickness(16, 10, 16, 10), Margin = new Thickness(0, 0, 10, 0) };
            var save = new Button { Content = "Save session", IsDefault = true, Padding = new Thickness(16, 10, 16, 10) };
            actions.Children.Add(cancel); actions.Children.Add(save); panel.Children.Add(actions);
            save.Click += (_, _) =>
            {
                var amounts = new int[5];
                for (int i = 0; i < 5; i++)
                    if (!int.TryParse(inputs[i].Text.Trim(), out amounts[i]) || amounts[i] < 0)
                    { MessageBox.Show(this, "Enter a non-negative whole number for " + PotionTrackerPanel.PotionNames[i] + "."); inputs[i].Focus(); return; }
                if (date.SelectedDate == null) { MessageBox.Show(this, "Choose a session date."); return; }
                var auraAmounts = new int[2];
                for (int i = 0; i < 2; i++)
                    if (!int.TryParse(auraInputs[i].Text.Trim(), out auraAmounts[i]) || auraAmounts[i] < 0)
                    { MessageBox.Show(this, "Enter a non-negative whole number for " + (biome == "Dreamspace" ? (i == 0 ? "Borealis" : "Dreammetric") : (i == 0 ? "Glitch" : "Oppression")) + "."); auraInputs[i].Focus(); return; }
                if (amounts.Sum(x => (long)x) == 0 && auraAmounts.Sum(x => (long)x) == 0)
                { MessageBox.Show(this, "Add at least one potion or aura to this session."); return; }
                Result = new PotionBiomeSession { Date = date.SelectedDate.Value.Date, Oblivion = amounts[0], Godlike = amounts[1], Heavenly = amounts[2], Bound = amounts[3], Goddess = amounts[4], Borealis = biome == "Dreamspace" ? auraAmounts[0] : 0, Dreammetric = biome == "Dreamspace" ? auraAmounts[1] : 0, Glitch = biome == "Glitched" ? auraAmounts[0] : 0, Oppression = biome == "Glitched" ? auraAmounts[1] : 0 };
                DialogResult = true;
            };
        }
    }
}

namespace CyberspaceTracker
{
    internal static class DreamspaceArt
    {
        internal static Brush Wave(FrameworkElement owner, string[] colours, double seconds = 2.8)
        {
            var brush = new LinearGradientBrush { StartPoint = new Point(0, 0), EndPoint = new Point(1, 0), SpreadMethod = GradientSpreadMethod.Repeat };
            for (int i = 0; i < colours.Length; i++)
                brush.GradientStops.Add(new GradientStop((Color)ColorConverter.ConvertFromString(colours[i]), (double)i / (colours.Length - 1)));
            var shift = new TranslateTransform();
            brush.RelativeTransform = shift;
            void Update()
            {
                shift.BeginAnimation(TranslateTransform.XProperty, owner.IsVisible ? new System.Windows.Media.Animation.DoubleAnimation(0, 1, TimeSpan.FromSeconds(seconds)) { RepeatBehavior = System.Windows.Media.Animation.RepeatBehavior.Forever } : null);
            }
            owner.Loaded += (_, _) => Update();
            owner.IsVisibleChanged += (_, _) => Update();
            owner.Unloaded += (_, _) => shift.BeginAnimation(TranslateTransform.XProperty, null);
            return brush;
        }
        private static void Animate(FrameworkElement owner, System.Windows.Media.Animation.Animatable target, DependencyProperty property, double from, double to, double seconds, bool reverse = false)
        {
            void Update() => target.BeginAnimation(property, owner.IsVisible ? new System.Windows.Media.Animation.DoubleAnimation(from, to, TimeSpan.FromSeconds(seconds)) { AutoReverse = reverse, RepeatBehavior = System.Windows.Media.Animation.RepeatBehavior.Forever } : null);
            owner.Loaded += (_, _) => Update();
            owner.IsVisibleChanged += (_, _) => Update();
            owner.Unloaded += (_, _) => target.BeginAnimation(property, null);
        }
        internal static TextBlock AuraLabel(string name, double size = 14)
        {
            var label = new TextBlock { Text = name, FontSize = size, FontWeight = FontWeights.Bold };
            label.Foreground = Wave(label, new[] { "#FF1493", "#FF1493", "#FFFFFF", "#FF1493", "#FF1493" }, 1.1);
            return label;
        }
        internal static FrameworkElement SideBorders()
        {
            var frame = new Border { IsHitTestVisible = false, BorderThickness = new Thickness(2), CornerRadius = new CornerRadius(8) };
            frame.BorderBrush = Wave(frame, new[] { "#FF46B6", "#FF46B6", "#FFFFFF", "#FFFFFF", "#FF46B6" }, 2.4);
            frame.Effect = new System.Windows.Media.Effects.DropShadowEffect { Color = Colors.HotPink, BlurRadius = 10, ShadowDepth = 0, Opacity = .5 };
            return frame;
        }
        internal static FrameworkElement Background()
        {
            var canvas = new Canvas { Width = 1100, Height = 650, ClipToBounds = true, IsHitTestVisible = false };
            var view = new Viewbox { Child = canvas, Stretch = Stretch.UniformToFill, IsHitTestVisible = false, Opacity = 0.85 };
            var baseLayer = new System.Windows.Shapes.Rectangle { Width = 1100, Height = 650, Fill = new LinearGradientBrush(Color.FromRgb(27, 9, 37), Color.FromRgb(72, 21, 66), 35) };
            canvas.Children.Add(baseLayer);
            for (int i = 0; i < 3; i++)
            {
                var mist = new System.Windows.Shapes.Ellipse { Width = 850, Height = 500, Fill = new RadialGradientBrush(Color.FromArgb(100, 245, 68, 205), Colors.Transparent) };
                Canvas.SetLeft(mist, -220 + i * 390); Canvas.SetTop(mist, -160 + i * 160);
                var drift = new TranslateTransform(); mist.RenderTransform = drift;
                Animate(view, drift, TranslateTransform.XProperty, -45, 65, 14 + i * 3, true);
                canvas.Children.Add(mist);
            }
            var orbit = new Canvas { Width = 440, Height = 440, RenderTransformOrigin = new Point(.5, .5), Opacity = .48 };
            Canvas.SetLeft(orbit, 620); Canvas.SetTop(orbit, 70);
            var spin = new RotateTransform(); orbit.RenderTransform = spin;
            Animate(view, spin, RotateTransform.AngleProperty, 0, 360, 90);
            for (int i = 0; i < 2; i++)
            {
                var ring = new System.Windows.Shapes.Ellipse { Width = 370 + i * 55, Height = 370 + i * 55, Stroke = PotionTrackerPanel.Colour("#E889DB"), StrokeThickness = 1.2, StrokeDashArray = new DoubleCollection { 5, 14 } };
                Canvas.SetLeft(ring, 35 - i * 27.5); Canvas.SetTop(ring, 35 - i * 27.5); orbit.Children.Add(ring);
            }
            var star = Star(220, 220, 155, 65);
            star.StrokeThickness = 3; star.Opacity = .8;
            star.Effect = new System.Windows.Media.Effects.DropShadowEffect { Color = Colors.HotPink, BlurRadius = 35, ShadowDepth = 0, Opacity = .9 };
            orbit.Children.Add(star); canvas.Children.Add(orbit);
            var title = AuraLabel("Dreammetric", 33); title.FontFamily = new FontFamily("Georgia"); title.Opacity = .65;
            Canvas.SetLeft(title, 720); Canvas.SetTop(title, 482); canvas.Children.Add(title);
            var random = new Random(32);
            for (int i = 0; i < 38; i++)
            {
                double x = random.Next(20, 1080), y = random.Next(20, 630);
                var sparkle = Star(x, y, random.Next(3, 10), 1.5);
                sparkle.Opacity = .2 + random.NextDouble() * .4;
                var floatUp = new TranslateTransform(); sparkle.RenderTransform = floatUp;
                Animate(view, floatUp, TranslateTransform.YProperty, 10, -20, 4 + random.Next(7), true);
                canvas.Children.Add(sparkle);
            }
            return new Grid { ClipToBounds = true, IsHitTestVisible = false, Children = { view } };
        }
        private static System.Windows.Shapes.Polygon Star(double x, double y, double outer, double inner)
        {
            var points = new PointCollection();
            for (int i = 0; i < 10; i++)
            {
                double angle = -Math.PI / 2 + i * Math.PI / 5;
                double radius = i % 2 == 0 ? outer : inner;
                points.Add(new Point(x + Math.Cos(angle) * radius, y + Math.Sin(angle) * radius));
            }
            return new System.Windows.Shapes.Polygon { Points = points, Stroke = PotionTrackerPanel.Colour("#FFB9F2"), StrokeThickness = 1, Fill = PotionTrackerPanel.Colour("#22FF87DC") };
        }
    }
}

namespace CyberspaceTracker
{
    internal static class GlitchedArt
    {
        // Every timer is owned by its visual and stops when hidden or unloaded.
        private static void TickWhileVisible(FrameworkElement owner, int milliseconds, Action tick, Action? reset = null)
        {
            var timer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(milliseconds) };
            timer.Tick += (_, _) => tick();
            void Update()
            {
                if (owner.IsLoaded && owner.IsVisible) timer.Start();
                else { timer.Stop(); reset?.Invoke(); }
            }
            owner.Loaded += (_, _) => Update();
            owner.IsVisibleChanged += (_, _) => Update();
            owner.Unloaded += (_, _) => { timer.Stop(); reset?.Invoke(); };
        }
        internal static Brush SelectionBrush(FrameworkElement owner)
        {
            var brush = new LinearGradientBrush { StartPoint = new Point(0, 0), EndPoint = new Point(1, .1) };
            brush.GradientStops.Add(new GradientStop(Color.FromRgb(12, 20, 31), 0));
            brush.GradientStops.Add(new GradientStop(Color.FromRgb(27, 46, 62), .45));
            brush.GradientStops.Add(new GradientStop(Color.FromRgb(44, 76, 86), .47));
            brush.GradientStops.Add(new GradientStop(Color.FromRgb(16, 24, 38), .50));
            brush.GradientStops.Add(new GradientStop(Color.FromRgb(29, 18, 43), 1));
            brush.BeginAnimation(Brush.OpacityProperty, new System.Windows.Media.Animation.DoubleAnimation(1, 1, TimeSpan.FromSeconds(1)) { RepeatBehavior = System.Windows.Media.Animation.RepeatBehavior.Forever });
            var random = new Random();
            TickWhileVisible(owner, 230, () =>
            {
                double position = .15 + random.NextDouble() * .65;
                brush.GradientStops[1].Offset = position;
                brush.GradientStops[2].Offset = position + .02;
                brush.GradientStops[3].Offset = position + .05;
                brush.GradientStops[2].Color = random.Next(3) == 0 ? Color.FromRgb(69, 39, 84) : Color.FromRgb(44, 76, 86);
            });
            return brush;
        }
        internal static FrameworkElement AuraLabel(string name)
        {
            var label = new CorruptedAuraText(name);
            TickWhileVisible(label, 115, label.Advance);
            return label;
        }
        internal static FrameworkElement BorderEffect()
        {
            var canvas = new Canvas { IsHitTestVisible = false, Margin = new Thickness(-16, -10, -16, -10) };
            var random = new Random();
            TickWhileVisible(canvas, 140, () =>
            {
                canvas.Children.Clear();
                double w = canvas.ActualWidth, h = canvas.ActualHeight;
                if (w < 1 || h < 1) return;
                for (int i = 0; i < 24; i++)
                {
                    bool horizontal = i % 2 == 0;
                    var brush = new SolidColorBrush(CorruptedAuraText.Palette[random.Next(CorruptedAuraText.Palette.Length)]);
                    var line = new System.Windows.Shapes.Rectangle { Width = horizontal ? random.Next(15, 100) : 2, Height = horizontal ? 2 : random.Next(10, 65), Fill = brush, Opacity = .65 };
                    Canvas.SetLeft(line, horizontal ? random.NextDouble() * Math.Max(0, w - 100) : (i % 4 == 1 ? 0 : w - 2));
                    Canvas.SetTop(line, horizontal ? (i % 4 == 0 ? 0 : h - 2) : random.NextDouble() * Math.Max(0, h - 65));
                    canvas.Children.Add(line);
                }
                for (int i = 0; i < 4; i++)
                {
                    var code = new TextBlock { Text = new string(Enumerable.Range(0, 5).Select(_ => CorruptedAuraText.Symbols[random.Next(CorruptedAuraText.Symbols.Length)]).ToArray()), FontFamily = new FontFamily("Consolas"), FontSize = 10, Foreground = new SolidColorBrush(CorruptedAuraText.Palette[random.Next(CorruptedAuraText.Palette.Length)]) };
                    Canvas.SetLeft(code, random.NextDouble() * Math.Max(0, w - 60)); Canvas.SetTop(code, i % 2 == 0 ? -5 : h - 10); canvas.Children.Add(code);
                }
            }, () => canvas.Children.Clear());
            return canvas;
        }
        internal static FrameworkElement Background()
        {
            var canvas = new Canvas { Width = 1100, Height = 650, Background = PotionTrackerPanel.Colour("#02050B"), IsHitTestVisible = false };
            var random = new Random(83);
            var fragments = new List<Border>();
            for (int i = 0; i < 35; i++)
            {
                double x = random.Next(1100), y = random.Next(120, 640);
                var block = new Border { Width = random.Next(25, 150), Height = random.Next(8, 65), Background = PotionTrackerPanel.Colour(i % 3 == 0 ? "#226CE7F2" : "#142575CA"), BorderBrush = PotionTrackerPanel.Colour("#426BCBDD"), BorderThickness = new Thickness(1), RenderTransform = new TranslateTransform() };
                Canvas.SetLeft(block, x); Canvas.SetTop(block, y); canvas.Children.Add(block); fragments.Add(block);
                if (i % 5 == 0)
                {
                    var glow = new System.Windows.Shapes.Ellipse { Width = 200, Height = 95, Fill = new RadialGradientBrush(Color.FromArgb(95, 130, 242, 255), Colors.Transparent) };
                    Canvas.SetLeft(glow, x - 50); Canvas.SetTop(glow, y - 25); canvas.Children.Add(glow);
                    for (int j = 0; j < 5; j++)
                    {
                        var scan = new System.Windows.Shapes.Rectangle { Width = 120, Height = 1, Fill = PotionTrackerPanel.Colour("#809DF7FF") };
                        Canvas.SetLeft(scan, x - j * 4); Canvas.SetTop(scan, y + j * 7); canvas.Children.Add(scan);
                    }
                }
            }
            var view = new Viewbox { Child = canvas, Stretch = Stretch.UniformToFill, IsHitTestVisible = false };
            var root = new Grid { ClipToBounds = true, IsHitTestVisible = false }; root.Children.Add(view);
            TickWhileVisible(root, 260, () =>
            {
                foreach (var block in fragments)
                {
                    var shift = (TranslateTransform)block.RenderTransform;
                    shift.X = random.Next(-12, 13); shift.Y = random.Next(-3, 4);
                    block.Opacity = .25 + random.NextDouble() * .65;
                }
            });
            return root;
        }
        internal static FrameworkElement Bursts()
        {
            var overlay = new Canvas { IsHitTestVisible = false, ClipToBounds = true };
            var random = new Random();
            var clock = new System.Diagnostics.Stopwatch();
            double nextBurst = 15, burstEnd = 0;
            void Reset() { clock.Reset(); nextBurst = 15; burstEnd = 0; overlay.Children.Clear(); }
            TickWhileVisible(overlay, 100, () =>
            {
                if (!clock.IsRunning) clock.Start();
                double now = clock.Elapsed.TotalSeconds;
                if (now >= nextBurst) { burstEnd = now + 1.4; nextBurst += 15; }
                overlay.Children.Clear();
                if (now >= burstEnd || overlay.ActualWidth < 1 || overlay.ActualHeight < 1) return;
                double width = overlay.ActualWidth, height = overlay.ActualHeight;
                for (int i = 0; i < 12; i++)
                {
                    var stripe = new System.Windows.Shapes.Rectangle { Width = random.Next(35, 220), Height = random.Next(3, 35), Opacity = .28, Fill = StripeBrush(i % 4 == 0 ? Colors.Yellow : (i % 3 == 0 ? Colors.Cyan : Colors.White)) };
                    Canvas.SetLeft(stripe, random.NextDouble() * width); Canvas.SetTop(stripe, random.NextDouble() * height); overlay.Children.Add(stripe);
                }
                for (int i = 0; i < 3; i++)
                {
                    var text = new TextBlock { Text = "⚠  << SERVER INFO >>\nERROR 0x" + random.Next(65535).ToString("X4") + "\nSIGNAL CORRUPTED // RETRY_", FontFamily = new FontFamily("Consolas"), FontSize = 13, FontWeight = FontWeights.Bold, Foreground = Brushes.Red };
                    var error = new Border { Child = text, Width = Math.Min(260, width), Padding = new Thickness(12), Background = PotionTrackerPanel.Colour("#DC080308"), BorderBrush = Brushes.Red, BorderThickness = new Thickness(1), Opacity = .65 };
                    Canvas.SetLeft(error, random.NextDouble() * Math.Max(0, width - 280)); Canvas.SetTop(error, random.NextDouble() * Math.Max(0, height - 100)); overlay.Children.Add(error);
                }
            }, Reset);
            return overlay;
        }
        private static Brush StripeBrush(Color colour)
        {
            var drawing = new DrawingGroup();
            drawing.Children.Add(new GeometryDrawing(Brushes.Black, null, new RectangleGeometry(new Rect(0, 0, 20, 20))));
            var path = Geometry.Parse("M -10,0 L 0,0 L 20,20 L 10,20 Z M 10,0 L 20,0 L 30,10 L 20,10 Z");
            drawing.Children.Add(new GeometryDrawing(new SolidColorBrush(colour), null, path));
            return new DrawingBrush(drawing) { TileMode = TileMode.Tile, ViewportUnits = BrushMappingMode.Absolute, Viewport = new Rect(0, 0, 20, 20) };
        }
    }
}

namespace CyberspaceTracker
{
    internal sealed class CorruptedAuraText : FrameworkElement
    {
        internal const string Symbols = "!@#$%^&*()";
        internal static readonly Color[] Palette = {
            Color.FromRgb(145, 46, 76), Color.FromRgb(106, 44, 139),
            Color.FromRgb(68, 60, 158), Color.FromRgb(43, 118, 80),
            Color.FromRgb(142, 151, 155)
        };
        private readonly string name;
        private readonly Random random = new();
        private string display;
        private Color colour;
        private double offset, scale = 1;
        private int frame;
        internal CorruptedAuraText(string name)
        {
            this.name = name;
            display = name;
            colour = name == "Oppression" ? Colors.LightGray : Palette[1];
            Height = 26; MinWidth = name == "Oppression" ? 132 : 95;
            ToolTip = name;
            System.Windows.Automation.AutomationProperties.SetName(this, name);
        }
        internal void Advance()
        {
            frame++;
            if (name == "Oppression")
            {
                display = new string(name.Select(c => random.Next(4) == 0 ? ' ' : (random.Next(2) == 0 ? char.ToUpperInvariant(c) : char.ToLowerInvariant(c))).ToArray());
                InvalidateVisual();
                return;
            }
            display = new string(name.Select(c => random.Next(7) == 0 ? Symbols[random.Next(Symbols.Length)] : (random.Next(2) == 0 ? char.ToUpperInvariant(c) : char.ToLowerInvariant(c))).ToArray());
            colour = name == "Oppression" ? (random.Next(3) == 0 ? Colors.Gray : Colors.White) : Palette[random.Next(Palette.Length)];
            offset = random.Next(-3, 4);
            scale = .88 + random.NextDouble() * .15;
            InvalidateVisual();
        }
        protected override Size MeasureOverride(Size availableSize) => new Size(MinWidth, 26);
        protected override void OnRender(DrawingContext dc)
        {
            base.OnRender(dc);
            if (name == "Oppression")
            {
                for (int i = 0; i < display.Length; i++)
                {
                    if (display[i] == ' ') continue;
                    var letter = new FormattedText(display[i].ToString(), System.Globalization.CultureInfo.InvariantCulture, FlowDirection.LeftToRight,
                        new Typeface(new FontFamily("Georgia"), FontStyles.Normal, FontWeights.Normal, FontStretches.Normal), 17, Brushes.White, VisualTreeHelper.GetDpi(this).PixelsPerDip);
                    dc.PushOpacity((frame + i * 3) % 7 == 0 ? .4 : 1);
                    dc.DrawText(letter, new Point(3 + i * 12.5, 2));
                    dc.Pop();
                }
                return;
            }
            var formatted = new FormattedText(display, System.Globalization.CultureInfo.InvariantCulture, FlowDirection.LeftToRight,
                new Typeface(new FontFamily("Consolas"), FontStyles.Normal, FontWeights.Bold, FontStretches.Normal), 18, Brushes.White, VisualTreeHelper.GetDpi(this).PixelsPerDip);
            var geometry = formatted.BuildGeometry(new Point(4, 1));
            var stroke = new SolidColorBrush(colour);
            var pen = new Pen(stroke, .85);
            var dark = new SolidColorBrush(Color.FromRgb(8, 7, 12));
            dc.PushTransform(new ScaleTransform(scale, 1));
            for (int i = 0; i < 4; i++)
            {
                dc.PushClip(new RectangleGeometry(new Rect(0, i * 6, Math.Max(ActualWidth, MinWidth), 6)));
                dc.PushTransform(new TranslateTransform(i == frame % 4 ? offset : 0, 0));
                dc.DrawGeometry(dark, pen, geometry);
                dc.Pop(); dc.Pop();
            }
            dc.Pop();
        }
    }
}


namespace CyberspaceTracker
{
    // Data lives outside the published app folder, so app updates keep every session.
    internal static class TrackerStorage
    {
        private static readonly string Folder = System.IO.Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "CyberspaceTracker");
        private static readonly System.Text.Json.JsonSerializerOptions Options = new()
        {
            WriteIndented = true,
            IgnoreReadOnlyProperties = true
        };
        private static readonly List<Func<bool>> pendingSaves = new();

        internal static bool Attach<T>(ObservableCollection<T> sessions, string filename) where T : class
        {
            string path = System.IO.Path.Combine(Folder, filename);
            string backup = path + ".bak";
            bool dirty = false;
            bool preserveBackup = false;
            bool loadBlocked = false;
            List<T> Read(string source)
            {
                var rows = System.Text.Json.JsonSerializer.Deserialize<List<T>>(System.IO.File.ReadAllText(source), Options);
                if (rows == null || rows.Any(row => row == null))
                    throw new System.IO.InvalidDataException("The session file contains invalid entries.");
                return rows;
            }
            try
            {
                if (System.IO.File.Exists(path))
                {
                    try
                    {
                        foreach (var row in Read(path)) sessions.Add(row);
                    }
                    catch (Exception)
                    {
                        // Recover the previous successful save without overwriting it with damaged data.
                        var recovered = Read(backup);
                        System.IO.File.Copy(path, path + ".damaged-" + Guid.NewGuid().ToString("N"));
                        foreach (var row in recovered) sessions.Add(row);
                        preserveBackup = true;
                        dirty = true;
                        MessageBox.Show("Recovered " + filename + " from its backup. The most recent change may be missing. The damaged file has been preserved.", "Sessions recovered", MessageBoxButton.OK, MessageBoxImage.Warning);
                    }
                }
                else if (System.IO.File.Exists(backup))
                {
                    foreach (var row in Read(backup)) sessions.Add(row);
                    preserveBackup = true;
                    dirty = true;
                }
            }
            catch (Exception ex)
            {
                loadBlocked = true;
                MessageBox.Show("Could not load " + filename + ". Existing files have not been overwritten. Saving for this tab is disabled until the load problem is fixed and the app is restarted.\n\nSave folder: " + Folder + "\n\n" + ex.Message,
                    "Unable to load sessions", MessageBoxButton.OK, MessageBoxImage.Error);
            }

            bool Save(bool showError)
            {
                if (!dirty) return true;
                if (loadBlocked) return false;
                string temporary = path + "." + Guid.NewGuid().ToString("N") + ".tmp";
                try
                {
                    System.IO.Directory.CreateDirectory(Folder);
                    // Preserve the pre-update data once per release, before touching the live save.
                    string previousSave = preserveBackup ? backup : path;
                    if (System.IO.File.Exists(previousSave))
                    {
                        string versionBackupFolder = System.IO.Path.Combine(Folder, "Backups", "before-v" + TrackerVersion.Current);
                        System.IO.Directory.CreateDirectory(versionBackupFolder);
                        string versionBackup = System.IO.Path.Combine(versionBackupFolder, filename);
                        if (!System.IO.File.Exists(versionBackup))
                            System.IO.File.Copy(previousSave, versionBackup, false);
                    }
                    byte[] bytes = System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(sessions.ToList(), Options);
                    using (var stream = new System.IO.FileStream(temporary, System.IO.FileMode.CreateNew, System.IO.FileAccess.Write, System.IO.FileShare.None))
                    {
                        stream.Write(bytes, 0, bytes.Length);
                        stream.Flush(true);
                    }
                    if (System.IO.File.Exists(path) && !preserveBackup)
                        System.IO.File.Replace(temporary, path, backup);
                    else
                        System.IO.File.Move(temporary, path, true);
                    preserveBackup = false;
                    dirty = false;
                    return true;
                }
                catch (Exception ex)
                {
                    if (showError)
                        MessageBox.Show("Your latest changes are still in memory but could not be saved. Please keep the app open and fix the problem.\n\nSave folder: " + Folder + "\n\n" + ex.Message,
                            "Unable to save sessions", MessageBoxButton.OK, MessageBoxImage.Error);
                    return false;
                }
                finally
                {
                    try { if (System.IO.File.Exists(temporary)) System.IO.File.Delete(temporary); }
                    catch { /* A leftover temporary file must not interrupt the app. */ }
                }
            }
            pendingSaves.Add(() => Save(false));
            sessions.CollectionChanged += (_, _) =>
            {
                dirty = true;
                if (loadBlocked)
                {
                    MessageBox.Show("This tab could not load its existing save file, so these changes cannot be saved. Fix the load problem before adding sessions.\n\n" + Folder,
                        "Saving unavailable", MessageBoxButton.OK, MessageBoxImage.Warning);
                    return;
                }
                Save(true);
            };
            if (dirty) Save(true);
            return !loadBlocked;
        }

        internal static bool FlushPending()
        {
            bool success = true;
            foreach (var save in pendingSaves) if (!save()) success = false;
            return success;
        }
    }
}

namespace CyberspaceTracker
{
    internal static class TrackerVersion
    {
        // The project Version property is the single source for the visible release number.
        internal static string Current { get; } = GetVersion();
        private static string GetVersion()
        {
            var assembly = typeof(TrackerVersion).Assembly;
            var info = System.Reflection.CustomAttributeExtensions.GetCustomAttribute<System.Reflection.AssemblyInformationalVersionAttribute>(assembly);
            return (info?.InformationalVersion ?? assembly.GetName().Version?.ToString(3) ?? "1.0.0").Split('+')[0];
        }
    }
}
